/// The client side of `bead.validations.v1.ValidationsService`, over one Bead client: a requester of each procedure its server answers, by its name.
#[derive(Debug, Clone)]
pub struct ValidationsClient {
    procedures: &'static ValidationsProcedures,
    service: ::bead::ServiceClient,
    request: ValidationsRequesters,
    notifications: ValidationsNotifications,
}

impl ValidationsClient {
    /// The client side of `bead.validations.v1.ValidationsService`, over `client`, given its options: whether it validates, and the windows of its notifications.
    ///
    /// # Errors
    ///
    /// A [`ProgrammerError`](::bead::ProgrammerError) where the runtime refuses the service; for a window of 0, a second client side over one client at another window, or a procedure its router refuses to declare.
    pub fn new(client: &::bead::Client, options: &ValidationsClientOptions) -> Result<Self, ::bead::ProgrammerError> {
        let procedures = ValidationsProcedures::get()?;
        let mut layer = ::bead::ServiceClientOptions::default();

        layer.fail_fast = options.fail_fast;
        layer.validates = options.validates;

        let service = ::bead::ServiceClient::new(procedures.all(), client, &layer)?;
        let request = ValidationsRequesters {
            judge_numbers: service.requester_of(&procedures.judge_numbers)?,
            judge_floats: service.requester_of(&procedures.judge_floats)?,
            judge_strings: service.requester_of(&procedures.judge_strings)?,
            judge_bytes: service.requester_of(&procedures.judge_bytes)?,
            judge_enums: service.requester_of(&procedures.judge_enums)?,
            judge_repeated: service.requester_of(&procedures.judge_repeated)?,
            judge_maps: service.requester_of(&procedures.judge_maps)?,
            judge_presence: service.requester_of(&procedures.judge_presence)?,
            judge_wrappers: service.requester_of(&procedures.judge_wrappers)?,
            judge_oneofs: service.requester_of(&procedures.judge_oneofs)?,
            judge_nested: service.requester_of(&procedures.judge_nested)?,
            judge_order: service.requester_of(&procedures.judge_order)?,
            judge_patterns: service.requester_of(&procedures.judge_patterns)?,
        };
        let notifications = ValidationsNotifications;

        Ok(Self {
            procedures,
            service,
            request,
            notifications,
        })
    }

    /// The requester of each procedure its server answers, by its name.
    #[must_use]
    pub const fn request(&self) -> &ValidationsRequesters {
        &self.request
    }

    /// The notification of each procedure that notifies, at the window its options gave, or unpaced.
    #[must_use]
    pub const fn notifications(&self) -> &ValidationsNotifications {
        &self.notifications
    }
}

